head.b:skin:
/* ============================================================
   CSS THEME THẬT — sinh tự động bởi theme/cssmerge.py
   KHÔNG sửa tay file này: sửa ở preview_template.html /
   reader_template.html rồi chạy lại cssmerge + build_theme.
   ============================================================ */

/* ---- trang chủ / thư viện ---- */
*{box-sizing:border-box}
html, body{margin:0;padding:0}
body{background:#0b0c10;color:#e9ebf2;font:15px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}
svg{display:block}
.tbtn{background:#1a1e2a;border:1px solid #2a2e42;color:#a6adc4;font:inherit;font-size:12px;font-weight:700;padding:7px 12px;border-radius:9px;cursor:pointer}
.tbtn.on{border-color:#ff8aa0;color:#ff8aa0}
.tb-note{color:#7d84a0;font-size:12px;margin-left:auto}
@media(max-width:900px){
  .tb-note{display:none}
}
.wrap{max-width:1180px;margin:0 auto;padding:18px 16px 80px}
.dots{display:flex;gap:6px}
.dots i{width:9px;height:9px;border-radius:50%;background:#33384f;display:block}
#app{
  --bg:#fff8f5; --surf:#fff; --surf2:#fff1ec; --surf3:#ffe7de;
  --txt:#3b2f35; --mut:#7d6e76; --acc:#ff7d9c; --acc2:#ffc48c;
  --bd:#ffe4e9; --bd2:#ffd0da;
  --r:16px; --r-lg:20px; --r-sm:11px;
  --sh:0 3px 12px rgba(255,125,156,.10); --sh-lg:0 16px 38px rgba(255,125,156,.18);
  --edge:inset 0 1px 0 rgba(255,255,255,.85); --ring:rgba(255,125,156,.45);
  --poshadow:0 10px 26px rgba(255,125,156,.22);
  --bad:#e5484d; --badtx:#fff; --newbg:#fff; --newtx:#111;
  --head:"Avenir Next","Segoe UI",system-ui,-apple-system,sans-serif;
  --body:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif;
  --chipbg:#ffeef2; --chiptx:#a35f70; --chipbd:#ffdbe3;
  --st-done:#2f9e6b; --st-run:#d98410; --st-soon:#7c6bd6;
  --stpillbg:#ffffff; --stpillbd:rgba(20,10,16,.08);
  --st-done-tx:#1d7752; --st-run-tx:#8f5c0a; --st-soon-tx:#53419f;
  --cap1:rgba(246,169,188,0); --cap2:rgba(245,163,184,.5); --cap3:rgba(245,162,183,.88); --captx:#fff;
  --capSoftA:rgba(246,169,188,.72); --capSoftB:rgba(246,169,188,0);
  --heroA:radial-gradient(700px 320px at 88% 0%, rgba(255,196,140,.34), transparent 62%),radial-gradient(560px 300px at 2% 24%, rgba(255,125,156,.20), transparent 60%),linear-gradient(180deg,#fff4ef,#fff);
  --hdrbg:rgba(255,248,245,.88)}
#app[data-dir="ctoi"]{
  --bg:#120e13; --surf:#1a1419; --surf2:#221b21; --surf3:#2d242a;
  --txt:#f5ebef; --mut:#a5949e; --acc:#ff8fab; --acc2:#ffc98f;
  --bd:rgba(255,255,255,.075); --bd2:rgba(255,255,255,.16);
  --sh:0 4px 18px rgba(0,0,0,.45); --sh-lg:0 24px 56px rgba(0,0,0,.62);
  --edge:inset 0 1px 0 rgba(255,255,255,.055); --ring:rgba(255,143,171,.55);
  --poshadow:0 12px 30px rgba(0,0,0,.55);
  --bad:#e0313c; --badtx:#fff; --newbg:#f5ebef; --newtx:#1a1419;
  --chipbg:#251e24; --chiptx:#e2ccd5; --chipbd:rgba(255,255,255,.11);
  --st-done:#3fd08d; --st-run:#f0a94a; --st-soon:#a797f2;
  --stpillbg:#251d23; --stpillbd:rgba(255,255,255,.15);
  --st-done-tx:#74e6b0; --st-run-tx:#ffc978; --st-soon-tx:#c3b6ff;
  --cap1:rgba(18,12,17,0); --cap2:rgba(18,12,17,.62); --cap3:rgba(13,8,12,.94); --captx:#fff;
  --capSoftA:rgba(255,143,171,.26); --capSoftB:rgba(255,143,171,0);
  --heroA:radial-gradient(760px 340px at 88% -6%, rgba(255,201,143,.15), transparent 62%),radial-gradient(620px 330px at 0% 16%, rgba(255,105,148,.20), transparent 60%),linear-gradient(180deg,#1e151b 0%,#160f15 56%,#120e13 100%);
  --hdrbg:rgba(19,14,19,.82)}
#app[data-dir="a"]{
  --bg:#fff; --surf:#fff; --surf2:#f6f6f8; --surf3:#ededf1;
  --txt:#16161a; --mut:#5f6672; --acc:#e8577a; --acc2:#f09070;
  --bd:#e9e9ef; --bd2:#dbdbe3;
  --r:12px; --r-lg:16px; --r-sm:9px;
  --sh:0 2px 8px rgba(18,18,28,.06); --sh-lg:0 14px 34px rgba(18,18,28,.10);
  --edge:inset 0 1px 0 rgba(255,255,255,.9); --ring:rgba(232,87,122,.4);
  --poshadow:0 10px 24px rgba(18,18,28,.14);
  --bad:#d92d38; --badtx:#fff; --newbg:#16161a; --newtx:#fff;
  --head:"Georgia","Times New Roman",serif;
  --chipbg:#f1f2f5; --chiptx:#48505e; --chipbd:#e4e5ec;
  --st-done:#2c9c68; --st-run:#cf8212; --st-soon:#6f63cf;
  --stpillbg:#ffffff; --stpillbd:rgba(16,16,24,.09);
  --st-done-tx:#1c7a50; --st-run-tx:#8a5a09; --st-soon-tx:#4c3fa8;
  --cap1:rgba(190,150,165,0); --cap2:rgba(185,140,158,.5); --cap3:rgba(176,130,148,.88); --captx:#fff;
  --capSoftA:rgba(190,150,165,.7); --capSoftB:rgba(190,150,165,0);
  --heroA:linear-gradient(180deg,#fdeef2,#fff 72%);
  --hdrbg:rgba(255,255,255,.88)}
.site{background:var(--bg);color:var(--txt);font-family:var(--body)}
.site svg{stroke:currentColor;fill:none;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round;width:15px;height:15px;flex:0 0 auto}
.hdr{position:sticky;top:0;z-index:30;background:var(--hdrbg);backdrop-filter:blur(10px);border-bottom:1px solid var(--bd)}
.hdr .in{max-width:1120px;margin:0 auto;padding:8px 16px;display:flex;align-items:center;gap:12px}
.logo{font-weight:900;font-size:17px;letter-spacing:-.03em}
.logo i{color:var(--acc);font-style:normal}
.nav{display:flex;gap:1px}
.nav a{padding:6px 10px;border-radius:var(--r-sm);font-size:13px;color:var(--mut);font-weight:600}
.nav a.on, .nav a:hover{background:var(--chipbg);color:var(--txt)}
.search{margin-left:auto;display:flex;align-items:center;gap:7px;background:var(--surf);border:1px solid var(--bd);border-radius:11px;padding:6px 11px;min-width:200px;transition:.2s}
.search:focus-within{border-color:var(--acc)}
.search input{border:0;background:transparent;outline:0;font:inherit;font-size:13px;color:var(--txt);width:100%}
.search svg{width:14px;height:14px;opacity:.5}
.ibtn{width:32px;height:32px;border-radius:9px;border:1px solid var(--bd);background:var(--surf);display:flex;align-items:center;justify-content:center;cursor:pointer;flex:0 0 auto;transition:.18s}
.ibtn svg{width:15px;height:15px}
.ibtn:hover{border-color:var(--acc);color:var(--acc)}
@media(max-width:900px){
  .nav{display:none}
}
@media(max-width:700px){
  .search{min-width:0;flex:1}
}
.hero{background:var(--heroA);border-bottom:1px solid var(--bd);position:relative;overflow:hidden}
.htimer{position:absolute;top:0;left:0;right:0;height:2px;background:transparent;z-index:6}
.htimer i{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--acc),var(--acc2));opacity:.85}
.hero .stage{position:relative;max-width:1120px;margin:0 auto;min-height:412px}
.slide{position:absolute;inset:0;padding:36px 16px 30px;opacity:0;visibility:hidden;
  transition:opacity .65s ease,visibility .65s;display:grid;grid-template-columns:1.25fr .75fr;gap:26px;align-items:center;max-width:1120px;margin:0 auto}
.slide.on{opacity:1;visibility:visible;position:relative}
@media(max-width:860px){
  .slide{grid-template-columns:1fr;gap:14px;padding:22px 16px 18px}
  .slide .media{order:-1}
}
.slide h1{font-family:var(--head);font-size:clamp(25px,3.4vw,38px);line-height:1.12;margin:12px 0 10px;letter-spacing:-.015em;font-weight:800}
.eyebrow{display:inline-flex;align-items:center;gap:7px;font-size:11.5px;font-weight:800;letter-spacing:.13em;text-transform:uppercase;
  color:var(--acc);background:var(--surf);border:1px solid var(--bd);padding:5px 12px;border-radius:999px}
.hmeta{color:var(--mut);font-size:14.5px;margin:0 0 10px;display:flex;flex-wrap:wrap;gap:5px 12px;align-items:center}
.hmeta b{color:var(--txt);font-weight:700}
.stpill{display:inline-flex;align-items:center;gap:5px;font-size:10px;font-weight:800;letter-spacing:.03em;text-transform:uppercase;
  padding:3px 9px;border-radius:999px;background:var(--stpillbg);border:1px solid var(--stpillbd);backdrop-filter:none}
.stpill.done{color:var(--st-done-tx)}
.stpill.run{color:var(--st-run-tx)}
.stpill.soon{color:var(--st-soon-tx)}
.stpill .d{width:6px;height:6px;border-radius:50%}
.stpill.done .d{background:var(--st-done)}
.stpill.run .d{background:var(--st-run)}
.stpill.soon .d{background:var(--st-soon)}
.stpill.run .d{animation:pulse 1.5s ease-in-out infinite}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:.35}}
.btns{display:flex;gap:9px;flex-wrap:wrap;margin:18px 0 0}
.btn{display:inline-flex;align-items:center;gap:7px;border:0;border-radius:var(--r-sm);padding:11px 19px;line-height:1.2;font:inherit;font-weight:800;font-size:13.5px;cursor:pointer;
  transition:transform .16s,box-shadow .16s,filter .16s}
.btn svg{width:17px;height:17px}
.btn.primary{background:linear-gradient(120deg,var(--acc),var(--acc2));color:#fff;box-shadow:0 8px 18px rgba(255,143,174,.32)}
.btn.ghost{background:var(--surf);color:var(--txt);border:1px solid var(--bd)}
.btn.ghost:hover{border-color:var(--acc);color:var(--acc)}
.btn.icon{padding:11px 14px}
.btn:hover{transform:translateY(-1px)}
.media{display:flex;justify-content:center}
.hcover{position:relative;border-radius:var(--r-lg);overflow:hidden;box-shadow:0 18px 40px rgba(226,120,150,.30),0 3px 10px rgba(0,0,0,.08)}
.hcover::after{content:"";position:absolute;left:0;right:0;bottom:0;height:38%;z-index:1;pointer-events:none;
  background:linear-gradient(180deg,var(--cap1) 0%,var(--cap2) 48%,var(--cap3) 100%)}
.hcover .hpill{position:absolute;left:0;right:0;bottom:0;z-index:2;display:flex;align-items:center;gap:8px;padding:10px 12px}
.hcover .hpill b{font-size:13px;font-weight:800;color:#fff;text-shadow:0 1px 2px rgba(122,32,70,.7),0 0 7px rgba(122,32,70,.5)}
.hcover .hpill em{margin-left:auto;font-style:normal;font-weight:800;font-size:12.5px;color:#fff;opacity:.96;
  text-shadow:0 1px 2px rgba(122,32,70,.7),0 0 7px rgba(122,32,70,.5)}
.hcover img{width:min(256px,58vw);aspect-ratio:3/4;object-fit:cover;display:block;border-radius:var(--r-lg);transition:transform 8s linear}
.slide.on .hcover img{transform:scale(1.028)}
@media(prefers-reduced-motion:reduce){
  .slide.on .hcover img{transform:none}
}
.h18{position:absolute;top:11px;left:11px;z-index:3;background:var(--bad);color:var(--badtx);font-size:10.5px;font-weight:900;padding:3px 8px;border-radius:7px}
.sctl{display:flex;align-items:center;gap:12px;margin-top:20px}
.sbtn{width:33px;height:33px;border-radius:50%;border:1px solid var(--bd);background:var(--surf);display:flex;align-items:center;justify-content:center;cursor:pointer;transition:.18s}
.sbtn svg{width:15px;height:15px}
.sbtn:hover{background:var(--acc);color:#fff;border-color:transparent}
.sdots{display:flex;gap:6px;align-items:center}
.sdots button{width:8px;height:8px;border-radius:50%;border:0;background:var(--bd2);cursor:pointer;padding:0;transition:.25s}
.sdots button.on{background:var(--acc);width:22px;border-radius:999px}
.scount{font-size:12.5px;font-weight:800;color:var(--mut)}
.stats{max-width:1120px;margin:0 auto;padding:14px 16px 2px;display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
@media(max-width:620px){
  .stats{grid-template-columns:repeat(2,1fr)}
}
.stat{background:var(--surf);border:1px solid var(--bd);border-radius:var(--r);padding:12px 15px;box-shadow:var(--sh);transition:.2s}
.stat:hover{transform:translateY(-2px);box-shadow:var(--sh-lg)}
.stat b{display:block;font-size:23px;letter-spacing:-.02em;font-family:var(--head);line-height:1.25}
.stat span{font-size:12.5px;color:var(--mut);font-weight:700;display:flex;align-items:center;gap:5px}
.stat svg{width:13px;height:13px;opacity:.7}
.sec{padding:18px 16px;max-width:1120px;margin:0 auto}
.sechead{display:flex;align-items:center;gap:9px;margin-bottom:11px;flex-wrap:wrap}
.sechead h2{font-family:var(--head);font-size:19px;margin:0;display:flex;align-items:center;gap:8px}
.sechead h2 svg{width:19px;height:19px;color:var(--acc)}
.sechead .sub{color:var(--mut);font-size:13px}
.sechead .right{margin-left:auto;display:flex;gap:8px;align-items:center}
.linkmore{font-size:13px;color:var(--acc);font-weight:800;display:inline-flex;align-items:center;gap:5px;cursor:pointer}
.linkmore svg{width:12px;height:12px}
.two{display:grid;grid-template-columns:1.1fr .9fr;gap:12px}
@media(max-width:860px){
  .two{grid-template-columns:1fr}
}
.panel{background:var(--surf);border:1px solid var(--bd);border-radius:var(--r-lg);padding:15px 17px;box-shadow:var(--sh)}
.rank{display:flex;align-items:center;gap:9px;padding:7px 0;border-bottom:1px dashed var(--bd);cursor:pointer;transition:.16s}
.rank:last-child{border-bottom:0}
.rank:hover{transform:translateX(2px)}
.rank .n{width:22px;height:22px;border-radius:7px;background:var(--chipbg);color:var(--mut);font-size:11.5px;font-weight:900;display:flex;align-items:center;justify-content:center;flex:0 0 auto}
.rank .n.top{background:linear-gradient(120deg,var(--acc),var(--acc2));color:#fff}
.rank .th{width:26px;height:36px;border-radius:6px;object-fit:cover;flex:0 0 auto;background:var(--surf2)}
.rank .tt{min-width:0;flex:1}
.rank .tt b{display:block;font-size:12.5px;font-weight:800;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.rank .tt span{font-size:11px;color:var(--mut)}
.rank .v{font-size:12px;color:var(--acc);font-weight:900;flex:0 0 auto}
.sched{display:flex;gap:9px;align-items:center;padding:7px 0;border-bottom:1px dashed var(--bd)}
.sched:last-child{border-bottom:0}
.sched .day{flex:0 0 40px;text-align:center;font-size:10px;font-weight:900;color:var(--acc);background:var(--chipbg);border:1px solid var(--chipbd);border-radius:8px;padding:5px 0;line-height:1.25}
.sched .info{min-width:0}
.sched .info b{display:block;font-size:12.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.sched .info span{font-size:11px;color:var(--mut)}
.ltabs{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:9px}
.ltab{display:inline-flex;align-items:center;gap:7px;background:var(--surf2);border:1px solid var(--bd);color:var(--mut);
  font:inherit;font-size:12.5px;font-weight:800;padding:6px 12px;border-radius:999px;cursor:pointer;transition:.16s}
.ltab svg{width:13px;height:13px}
.ltab .ct{font-size:10.5px;font-weight:900;opacity:.85;background:var(--chipbg);border-radius:999px;padding:1px 6px}
.ltab.on{background:linear-gradient(120deg,var(--acc),var(--acc2));color:#fff;border-color:transparent}
.ltab.on .ct{background:rgba(255,255,255,.26);opacity:1}
.sgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(216px,1fr));gap:8px}
.srow{display:flex;align-items:center;gap:9px;background:var(--surf2);border:1px solid var(--bd);
  border-radius:var(--r-sm);padding:7px 9px;cursor:pointer;text-align:left;font:inherit;color:var(--txt);
  transition:background .18s ease,color .18s ease,border-color .18s ease,transform .18s ease,box-shadow .18s ease}
.srow:hover{transform:translateY(-1px)}
.srow .sc{flex:0 0 auto;display:flex}
.srow .sc img{width:34px;height:46px;object-fit:cover;border-radius:5px;display:block;background:var(--surf3);box-shadow:var(--sh)}
.srow .sc img+img{margin-left:-15px;box-shadow:0 0 0 1.5px var(--surf2),var(--sh)}
.srow .st{min-width:0;flex:1}
.srow .st b{display:block;font-size:12.5px;font-weight:800;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.srow .st em{display:block;font-style:normal;font-size:11px;color:var(--mut);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.srow .mul{flex:0 0 auto;font-size:10px;font-weight:900;background:var(--acc);color:#fff;border-radius:999px;padding:2px 7px}
.lempty{border:1px dashed var(--bd2);border-radius:var(--r);padding:14px;color:var(--mut);font-size:12.5px;background:var(--surf2);line-height:1.65}
.lempty b{color:var(--txt)}
.lempty code{background:var(--chipbg);border:1px solid var(--chipbd);border-radius:5px;padding:1px 5px;font-size:11.5px;color:var(--chiptx)}
.lempty button{margin-top:9px}
.filterbox{background:var(--surf);border:1px solid var(--bd);border-radius:var(--r-lg);padding:12px;box-shadow:var(--sh)}
.tabs{display:flex;gap:6px;overflow-x:auto;padding-bottom:2px}
.tab{white-space:nowrap;background:var(--surf2);border:1px solid var(--bd);color:var(--mut);font:inherit;font-size:12.5px;font-weight:700;padding:5px 11px;line-height:1.35;border-radius:999px;cursor:pointer;transition:.16s;display:inline-flex;align-items:center;gap:6px}
.tab:hover{color:var(--txt)}
.tab.on{background:linear-gradient(120deg,var(--acc),var(--acc2));color:#fff;border-color:transparent}
.tab .ct{font-size:10.5px;opacity:.75;font-weight:800}
.fbar{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px;align-items:center}
.fdrop{position:relative}
.fbtn{display:inline-flex;align-items:center;gap:7px;background:var(--surf2);border:1px solid var(--bd);color:var(--txt);font:inherit;font-size:12.5px;font-weight:700;padding:7px 11px;border-radius:var(--r-sm);cursor:pointer;transition:.16s}
.fbtn svg{width:12px;height:12px;opacity:.6}
.fbtn:hover{border-color:var(--acc)}
.fbtn.act{border-color:var(--acc);color:var(--acc)}
.fpanel{position:absolute;top:calc(100% + 7px);left:0;z-index:60;width:min(310px,86vw);background:var(--surf);border:1px solid var(--bd);border-radius:var(--r);box-shadow:var(--sh-lg);padding:10px;display:none}
.fpanel.open{display:block;animation:pop .16s ease}
@keyframes pop{from{opacity:0;transform:translateY(-5px)}to{opacity:1;transform:none}}
.fpanel .fsearch{width:100%;background:var(--surf2);border:1px solid var(--bd);border-radius:9px;padding:7px 10px;font:inherit;font-size:12.5px;color:var(--txt);outline:0;margin-bottom:8px}
.fpanel .flist{max-height:240px;overflow:auto;display:flex;flex-direction:column;gap:2px}
.fopt{display:flex;align-items:center;gap:8px;padding:7px 9px;border-radius:8px;font-size:13px;cursor:pointer;background:transparent;border:0;color:var(--txt);font-family:inherit;text-align:left;width:100%}
.fopt:hover{background:var(--surf2)}
.fopt.on{background:var(--chipbg);color:var(--acc);font-weight:800}
.fopt .n{margin-left:auto;font-size:11px;color:var(--mut);font-weight:700}
.fpick{display:flex;gap:6px;flex-wrap:wrap;margin-top:9px;align-items:center}
.fchip{display:inline-flex;align-items:center;gap:6px;background:var(--chipbg);border:1px solid var(--chipbd);color:var(--chiptx);font-size:12.5px;font-weight:700;padding:5px 11px;border-radius:999px}
.fchip svg{width:11px;height:11px;cursor:pointer}
.fclear{background:transparent;border:0;color:var(--acc);font:inherit;font-size:11.5px;font-weight:800;cursor:pointer;padding:4px 2px}
.fcount{color:var(--mut);font-size:12.5px;margin-top:8px}
.sortsel{margin-left:auto;background:var(--surf2);border:1px solid var(--bd);color:var(--txt);font:inherit;font-size:12.5px;font-weight:600;padding:7px 10px;border-radius:var(--r-sm);cursor:pointer;outline:0}
@media(max-width:700px){
  .sortsel{margin-left:0;width:100%}
}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(172px,1fr));gap:16px;margin-top:16px}
@media(max-width:600px){
  .grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
}
.card{cursor:pointer;opacity:0;transform:translateY(14px);transition:opacity .45s ease,transform .45s cubic-bezier(.2,.7,.3,1)}
.card.in{opacity:1;transform:none}
@media(prefers-reduced-motion:reduce){
  .card{opacity:1;transform:none;transition:none}
}
.card .th{position:relative;border-radius:var(--r);overflow:hidden;background:var(--surf2);box-shadow:var(--sh);transition:box-shadow .28s,transform .28s}
.card .th img{width:100%;aspect-ratio:3/4;object-fit:cover;display:block;transition:transform .4s cubic-bezier(.2,.7,.3,1)}
.card:hover .th{box-shadow:0 16px 32px rgba(226,120,150,.34),0 4px 12px rgba(0,0,0,.07);transform:translateY(-4px)}
.card:hover .th img{transform:scale(1.05)}
.corner{position:absolute;top:6px;right:6px;z-index:3;display:flex;flex-direction:column;gap:3px;align-items:flex-end}
.c18{background:var(--bad);color:var(--badtx);font-size:8.5px;font-weight:900;padding:2px 5px;border-radius:5px}
.cnew{background:var(--newbg);color:var(--newtx);font-size:8px;font-weight:900;padding:2px 5px;border-radius:5px;letter-spacing:.04em}
.stpill.corner-pill{position:absolute;top:6px;left:6px;z-index:3;font-size:7.5px;font-weight:800;letter-spacing:.01em;padding:2px 7px;gap:4px}
.stpill.corner-pill .d{width:5px;height:5px}
.cap{position:absolute;left:0;right:0;bottom:0;z-index:3;display:flex;align-items:center;gap:8px;padding:6px 10px;
  border-radius:0 0 var(--r) var(--r);
  background:linear-gradient(180deg,var(--cap1) 0%,var(--cap2) 46%,var(--cap3) 100%)}
.cap b{font-size:12.5px;font-weight:800;color:#fff;text-shadow:0 1px 2px rgba(122,32,70,.7),0 0 7px rgba(122,32,70,.5);letter-spacing:.01em}
.cap .mini{flex:1;height:3.5px;background:rgba(120,40,74,.26);border-radius:9px;overflow:hidden}
.cap .mini u{display:block;height:100%;background:#fff;border-radius:9px;box-shadow:0 0 3px rgba(90,20,50,.35)}
.hsyn{color:var(--mut);font-size:15px;line-height:1.62;margin:0;max-width:60ch;
  display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.card h3{font-size:14.5px;margin:10px 0 4px;line-height:1.28;font-weight:800;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;transition:color .18s}
.card:hover h3{color:var(--acc)}
.card .cb{font-size:12px;color:var(--mut);display:flex;flex-direction:column;gap:2px}
.card .cb i{display:flex;align-items:center;gap:5px;font-style:normal;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.card .cb svg{width:12.5px;height:12.5px;opacity:.7}
.card .cb .cp{color:var(--acc);font-weight:800}
.empty{color:var(--mut);padding:22px 0;text-align:center}
.empty .big{font-size:14px;font-weight:800;color:var(--txt);margin-bottom:5px}
.pager{display:flex;flex-direction:column;align-items:center;gap:8px;margin-top:18px}
.pager .pgbtns{display:flex;gap:6px;flex-wrap:wrap;justify-content:center}
.pg{min-width:32px;height:32px;padding:0 9px;line-height:1.2;display:inline-flex;align-items:center;justify-content:center;gap:5px;
  border-radius:9px;border:1px solid var(--bd);background:var(--surf);font-size:12.5px;font-weight:800;cursor:pointer;transition:.16s;color:var(--txt)}
.pg svg{width:13px;height:13px}
.pg:hover{border-color:var(--acc);color:var(--acc)}
.pg.on{background:linear-gradient(120deg,var(--acc),var(--acc2));color:#fff;border-color:transparent}
.pg.off{opacity:.4;pointer-events:none}
.pg.dots{border:0;background:transparent;cursor:default;pointer-events:none}
.pginfo{font-size:11.5px;color:var(--mut)}
.dwrap{padding:18px 16px 26px;max-width:1120px;margin:0 auto}
.dtop{display:grid;grid-template-columns:262px 1fr;gap:26px;align-items:start}
@media(max-width:780px){
  .dtop{grid-template-columns:1fr;gap:14px}
}
.coverbox{position:relative;width:100%;border-radius:var(--r-lg);overflow:hidden;box-shadow:var(--sh-lg);background:var(--surf2)}
.coverbox img{width:100%;height:auto;display:block}
.coverbox .ribbon{position:absolute;left:0;right:0;bottom:0;padding:8px 11px;display:flex;align-items:center;gap:7px;
  font-size:10.5px;font-weight:900;text-transform:uppercase;letter-spacing:.05em;color:#fff;border-radius:0 0 var(--r-lg) var(--r-lg)}
.coverbox .ribbon .sp{margin-left:auto;text-transform:none;letter-spacing:0;font-weight:800;opacity:.92}
.coverbox .c18{position:absolute;top:8px;left:8px;z-index:2;background:var(--bad);color:var(--badtx);font-size:9.5px;font-weight:900;padding:2px 6px;border-radius:6px}
.dinfo h1{font-family:var(--head);font-size:clamp(24px,3.2vw,32px);margin:0 0 9px;letter-spacing:-.01em}
.dmeta{color:var(--mut);font-size:13.5px;margin:0 0 12px;display:flex;flex-wrap:wrap;gap:5px 12px;align-items:center}
.dmeta b{color:var(--txt)}
.dtable{display:grid;grid-template-columns:repeat(auto-fit,minmax(118px,1fr));gap:8px;margin:0 0 13px}
.dtable .r{background:var(--surf2);border:1px solid var(--bd);border-radius:var(--r-sm);padding:7px 10px}
.dtable .r span{display:block;font-size:10.5px;color:var(--mut);font-weight:800;text-transform:uppercase;letter-spacing:.06em;margin-bottom:1px}
.dtable .r b{font-size:13.5px}
.chapbar{display:flex;gap:8px;align-items:center;margin:12px 0 10px;flex-wrap:wrap}
.chapbar .search{margin-left:0;flex:1;min-width:170px}
.chapgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(176px,1fr));gap:8px}
.cha{display:flex;align-items:center;gap:9px;background:var(--surf);border:1px solid var(--bd);border-radius:var(--r-sm);padding:9px 11px;line-height:1.3;font-size:13.5px;font-weight:600;cursor:pointer;transition:.16s}
.cha:hover{border-color:var(--acc);color:var(--acc)}
.cha.now{border-color:var(--acc);background:var(--chipbg)}
.cha .no{flex:0 0 auto;font-size:10px;font-weight:900;color:var(--acc);background:var(--chipbg);border-radius:6px;padding:2px 6px}
.cha .nm{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.cha .done{margin-left:auto;color:var(--acc)}
.cha .done svg{width:12px;height:12px}
.relcols{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:14px;margin-top:4px}
@media(max-width:860px){
  .relcols{grid-template-columns:1fr}
}
.relbox{display:grid;grid-template-columns:repeat(auto-fill,minmax(124px,1fr));gap:11px;margin-top:8px}
@media(hover:hover){
  #app.fx .stpill, #app.fx .h18, #app.fx .c18, #app.fx .cnew, #app.fx .fchip, #app.fx .nav a, #app.fx .eyebrow, #app.fx .linkmore, #app.fx .fclear, #app.fx .rank .n, #app.fx .sched .day, #app.fx .lbox .lh .cnt, #app.fx .cha .no, #app.fx .cha .done, #app.fx .fopt.on, #app.fx .fbtn.act, #app.fx .dtable .r, #app.fx .fpart, #app.fx .ltab{
