  #app.fx .tab:hover, #app.fx .ltab:hover{
  background-image:none;background:var(--mut);color:var(--surf2);border-color:var(--mut);
  box-shadow:var(--poshadow);
  transition:background .18s ease,color .18s ease,border-color .18s ease,box-shadow .18s ease}
  #app.fx .btn.primary:hover, #app.fx .tab.on:hover, #app.fx .ltab.on:hover, #app.fx .pg.on:hover, #app.fx .rank .n.top:hover{
  background-image:none;background:#fff;color:var(--acc);border-color:#fff;
  box-shadow:var(--poshadow);
  transition:background .18s ease,color .18s ease,border-color .18s ease,box-shadow .18s ease,transform .16s ease}
  #app.fx .nav a.on:hover, #app.fx .cha.now:hover{
  background-image:none;background:var(--txt);color:var(--chipbg);border-color:var(--txt);
  box-shadow:var(--poshadow);
  transition:background .18s ease,color .18s ease,border-color .18s ease,box-shadow .18s ease}
  #app.fx .fopt.on:hover{background:var(--acc);color:var(--chipbg);border-color:var(--acc)}
  #app.fx .eyebrow:hover{background:var(--acc);color:var(--surf);border-color:var(--acc)}
  #app.fx .fchip:hover{background:var(--chiptx);color:var(--chipbg);border-color:var(--chiptx)}
  #app.fx .fbtn.act:hover{background:var(--acc);color:var(--surf2);border-color:var(--acc)}
  #app.fx .linkmore:hover{background:var(--acc);color:var(--bg);border-radius:8px;padding:4px 9px}
  #app.fx .fclear:hover{background:var(--acc);color:var(--surf);border-radius:7px;padding:4px 7px}
  #app.fx .nav a:hover{background:var(--mut);color:var(--bg)}
  #app.fx .rank:hover .n{background:var(--mut);color:var(--chipbg)}
  #app.fx .rank:hover .n.top{background-image:none;background:#fff;color:var(--acc)}
  #app.fx .sched:hover .day{background:var(--acc);color:var(--chipbg);border-color:var(--acc)}
  #app.fx .srow, #app.fx .rank, #app.fx .sched, #app.fx .dtable .r{
  transition:background .18s ease,color .18s ease,border-color .18s ease,box-shadow .18s ease,
             padding .18s ease,margin .18s ease,transform .16s ease}
  #app.fx .srow:hover{background-image:none;background:var(--txt);border-color:var(--txt);box-shadow:var(--poshadow)}
  #app.fx .srow:hover .st b{color:var(--surf2)}
  #app.fx .srow:hover .st em{color:var(--surf2);opacity:.75}
  #app.fx .rank:hover{background-image:none;background:var(--txt);border-radius:var(--r-sm);
  box-shadow:var(--poshadow);padding-left:7px;padding-right:7px;margin-left:-7px;margin-right:-7px}
  #app.fx .rank:hover .tt b{color:var(--surf)}
