  #app.fx .rank:hover .v{color:var(--surf)}
  #app.fx .sched:hover{background-image:none;background:var(--txt);border-radius:var(--r-sm);
  box-shadow:var(--poshadow);padding-left:7px;padding-right:7px;margin-left:-7px;margin-right:-7px}
  #app.fx .sched:hover .info b, #app.fx .sched:hover .info span{color:var(--surf)}
  #app.fx .sched:hover .info span{opacity:.75}
  #app.fx .dtable .r:hover{background-image:none;background:var(--txt);border-color:var(--txt)}
  #app.fx .dtable .r:hover b{color:var(--surf2)}
  #app.fx .dtable .r:hover span{color:var(--surf2);opacity:.75}
  #app.fx .stpill.done:hover{background:var(--st-done-tx);color:var(--stpillbg);border-color:var(--st-done-tx)}
  #app.fx .stpill.run:hover{background:var(--st-run-tx);color:var(--stpillbg);border-color:var(--st-run-tx)}
  #app.fx .stpill.soon:hover{background:var(--st-soon-tx);color:var(--stpillbg);border-color:var(--st-soon-tx)}
  #app.fx .stpill:hover .d{background:currentColor;animation:none}
  #app.fx .h18:hover, #app.fx .c18:hover, #app.fx .coverbox .c18:hover{
