  #app.fx .cnew:hover{background:var(--newtx);color:var(--newbg);box-shadow:var(--poshadow)}
  #app.fx .card:hover .c18{background:var(--badtx);color:var(--bad)}
  #app.fx .card:hover .cnew{background:var(--newtx);color:var(--newbg)}
  #app.fx .card:hover .stpill.corner-pill.done{background:var(--st-done-tx);color:var(--stpillbg)}
  #app.fx .card:hover .stpill.corner-pill.run{background:var(--st-run-tx);color:var(--stpillbg)}
  #app.fx .card:hover .stpill.corner-pill.soon{background:var(--st-soon-tx);color:var(--stpillbg)}
  #app.fx .card:hover .stpill.corner-pill .d{background:currentColor;animation:none}
  #app.fx .sdots button:hover{background:var(--acc)}
  #app.fx .sdots button.on:hover{background:var(--txt)}
  #app.fx.fx-big .stat:hover{background:var(--txt);border-color:var(--txt);box-shadow:var(--sh-lg)}
