 down:'<path d="m6 10 6 6 6-6"/>',
 up:'<path d="m6 14 6-6 6 6"/>',
 play:'<path d="M7 4.5 19 12 7 19.5z"/>',
 bookmark:'<path d="M7 4h10v16l-5-4-5 4z"/>',
 share:'<circle cx="18" cy="5.5" r="2.5"/><circle cx="6" cy="12" r="2.5"/><circle cx="18" cy="18.5" r="2.5"/><path d="M8.3 10.8 15.7 6.7M8.3 13.2l7.4 4.1"/>',
 check:'<path d="m5 13 4.5 4.5L19 7"/>',
 moon:'<path d="M20 14.5A8.5 8.5 0 0 1 9.5 4a8.5 8.5 0 1 0 10.5 10.5z"/>',
 film:'<rect x="3" y="4.5" width="18" height="15" rx="2.5"/><path d="M8 4.5v15M16 4.5v15M3 12h18M3 8.2h5M3 15.8h5M16 8.2h5M16 15.8h5"/>',
 tv:'<rect x="3" y="7" width="18" height="13" rx="2.5"/><path d="m8.5 3 3.5 4 3.5-4"/>',
 x:'<path d="M6 6l12 12M18 6 6 18"/>',
 star:'<path d="m12 4 2.4 5 5.6.8-4 3.9 1 5.5-5-2.7-5 2.7 1-5.5-4-3.9 5.6-.8z"/>',
 fire:'<path d="M12 21a4 4 0 0 0 4-4c0-2-2-4-4-6-2 2-4 4-4 6a4 4 0 0 0 4 4z"/><path d="M12 3s2 2 2 4"/>'
};
const ic=n=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+(P[n]||'')+'</svg>';
const ric=()=>document.querySelectorAll('.ic[data-ic]').forEach(el=>{el.outerHTML=ic(el.dataset.ic);});ric();
new MutationObserver(()=>{if(document.querySelector('.ic[data-ic]'))ric();}).observe(document.documentElement,{childList:true,subtree:true});
const $=(s,r)=>(r||document).querySelector(s);
const $$=(s,r)=>Array.from((r||document).querySelectorAll(s));
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const uniq=a=>Array.from(new Set(a.filter(Boolean)));

const LIB=(window.CZREG||{}).lib||[];
const SERIES=(window.CZREG||{}).series||[];
const MOVIES=(window.CZREG||{}).movies||[];
const SLIDES=(window.CZREG||{}).slides||[];
const TODAY=new Date();
const authorFix=a=>String(a||'').replace(/&amp;/g,'&').replace(/&nbsp;/g,' ').replace(/\s+/g,' ').trim().replace(/^salmonlover$/i,'SalmonLover');
LIB.forEach(n=>{ n.author=authorFix(n.author); n.couple=String(n.couple||'').trim(); });
const stCls=s=> s==='Hoàn thành'?'done' : s==='Sắp ra mắt'?'soon' : 'run';
const isNew=n=>n.updated && (TODAY-new Date(n.updated))/864e5<=45;
const reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;

/* ===== HERO ===== */
let si=0,timer=null;const AUTO=8000;
function slideHTML(n,i){
  const st=stCls(n.status);
  return `<article class="slide ${i===0?'on':''}" data-i="${i}">
    <div>
      <span class="eyebrow">${ic('star')} ${i===0?'Truyện nổi bật':'Đề xuất cho bạn'}</span>
      <h1>${esc(n.title)}</h1>
      <div class="hmeta">
        <span class="stpill ${st}"><span class="d"></span>${esc(n.status)}</span>
        <span><b>${esc(n.countLabel)}</b></span>
        <span>${esc(n.author)}</span>
        ${n.couple?`<span>${esc(n.couple)}</span>`:''}
        <span>${esc(n.year)}</span>
      </div>
      <p class="hsyn">${esc(n.synFull||n.syn||'')}</p>
      <div class="btns">
        <button class="btn primary">${ic('play')} Đọc từ đầu</button>
        <button class="btn ghost">${ic('bookmark')} Thêm vào tủ</button>
      </div>
      <div class="sctl">
        <button class="sbtn" data-mv="-1" aria-label="Bộ trước">${ic('left')}</button>
        <div class="sdots">${SLIDES.map((_,k)=>`<button data-go="${k}" class="${k===i?'on':''}" aria-label="Bộ ${k+1}"></button>`).join('')}</div>
        <button class="sbtn" data-mv="1" aria-label="Bộ kế tiếp">${ic('right')}</button>
        <span class="scount">${i+1}/${SLIDES.length}</span>
      </div>
    </div>
    <div class="media"><div class="hcover">
      <img src="${n.slide||n.thumb||''}" alt="${esc(n.title)}" ${i===0?'':'loading="lazy"'} decoding="async">
      ${n.is18?'<span class="h18">18+</span>':''}
      <span class="hpill"><b>${esc(n.countLabel)}</b><em>${esc(n.author)}</em></span>
    </div></div>
  </article>`;
}
$('#stage').innerHTML=SLIDES.map(slideHTML).join('');
function goSlide(i){
  const all=$$('.slide');
  all[si].classList.remove('on');
  document.querySelectorAll('.sdots button')[si].classList.remove('on');
  si=(i+SLIDES.length)%SLIDES.length;
  all[si].classList.add('on');
  document.querySelectorAll('.sdots button')[si].classList.add('on');
  restartTimer();
}
function restartTimer(){
  const bar=$('#hTimer');bar.style.transition='none';bar.style.width='0%';
  clearInterval(timer);
  if(reduce) return;
  requestAnimationFrame(()=>{bar.style.transition='width '+AUTO+'ms linear';bar.style.width='100%';});
  timer=setInterval(()=>goSlide(si+1),AUTO);
}
$('#stage').addEventListener('click',e=>{
  const d=e.target.closest('[data-go]'); if(d){goSlide(+d.dataset.go);return;}
  const m=e.target.closest('[data-mv]'); if(m){goSlide(si+(+m.dataset.mv));}
});
$('.hero').addEventListener('mouseenter',()=>{clearInterval(timer);$('#hTimer').style.transition='none';});
$('.hero').addEventListener('mouseleave',restartTimer);
restartTimer();

$('#themeBtn').addEventListener('click',()=>{
  $('#app').dataset.dir = $('#app').dataset.dir==='ctoi' ? 'c' : 'ctoi';
  $$('#seg button').forEach(b=>b.classList.toggle('on',b.dataset.d===$('#app').dataset.dir));
});



$('#app').classList.add('fx');

/* ===== stats ===== */
$('#stats').innerHTML=[
 ['Tổng số bộ',LIB.length,'book'],
 ['Đã hoàn thành',LIB.filter(n=>n.status==='Hoàn thành').length,'check'],
 ['Đang cập nhật',LIB.filter(n=>n.status==='Đang cập nhật').length,'fire'],
 ['Đã chuyển thể',LIB.filter(n=>n.adapt).length,'film']
].map(([l,v,k])=>`<div class="stat"><b>${v}</b><span>${ic(k)} ${l}</span></div>`).join('');

/* ===== CARD ===== */
function card(n){
  const st=stCls(n.status);
  const parts=String(n.countLabel||'').split('/');
  const cur=parseInt(parts[0],10)||0, tot=parseInt(parts[1],10)||0;
  const pct=tot>0?Math.min(100,Math.round(cur/tot*100)):0;
  const img=n.thumb?`<img src="${n.thumb}" alt="${esc(n.title)}" loading="lazy" decoding="async">`
    :`<div style="aspect-ratio:3/4;background:linear-gradient(150deg,var(--chipbg),var(--surf2))"></div>`;
  const cap = st==='soon'
    ? `<span class="cap soon"><b>${esc(n.countLabel)}</b></span>`
    : `<span class="cap ${st}"><b>${esc(n.countLabel)}</b><i class="mini"><u style="width:${pct}%"></u></i></span>`;
  return `<article class="card" data-t="${esc(n.title)}" title="Mở trang truyện">
    <div class="th">${img}
      <span class="stpill corner-pill ${st}"><span class="d"></span>${esc(n.status)}</span>
      <span class="corner">${isNew(n)?'<span class="cnew">MỚI</span>':''}${n.is18?'<span class="c18">18+</span>':''}</span>
      ${cap}
    </div>
    <h3>${esc(n.title)}</h3>
    <div class="cb">
      <i>${ic('pen')} ${esc(n.author)}</i>
      ${n.couple?`<i class="cp">${ic('users')} ${esc(n.couple)}</i>`:''}
    </div></article>`;
}
const io=new IntersectionObserver(es=>{es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}});},{rootMargin:'0px 0px -40px 0px'});
function animateCards(root){
  $$('.card',root).forEach((c,i)=>{c.style.transitionDelay=Math.min(i*26,320)+'ms';io.observe(c);});
  clearTimeout(window.__revealT);
  window.__revealT=setTimeout(()=>{document.querySelectorAll('.card:not(.in)').forEach(el=>{el.style.transitionDelay='0ms';el.classList.add('in');});},1800);
}

/* ===== BXH + lịch ===== */
$('#rank').innerHTML=LIB.slice().sort((a,b)=>(b.chapters-a.chapters)||a.title.localeCompare(b.title,'vi')).slice(0,6)
 .map((n,i)=>`<div class="rank"><span class="n ${i<3?'top':''}">${i+1}</span>
   ${n.thumb?`<img class="th" src="${n.thumb}" alt="" loading="lazy">`:''}
   <span class="tt"><b>${esc(n.title)}</b><span>${esc(n.couple||n.author)}</span></span>
   <span class="v">${(2400-i*317).toLocaleString('vi-VN')}</span></div>`).join('');
$('#sched').innerHTML=[['T7','18:00','Lunar Secret','Chương 40 (ngoại truyện)'],['T7','20:30','Enemies With Benefits','Chương 60'],
 ['CN','09:00','Cô Vợ Hờ Đanh Đá Của Tôi','Chương 6'],['CN','21:00','VILLAIN STAR','Chương 33']]
 .map(([d,h,t,c])=>`<div class="sched"><div class="day">${d}<br>${h}</div><div class="info"><b>${esc(t)}</b><span>${esc(c)}</span></div></div>`).join('');

/* ===== Phân cấp chuyển thể — dữ liệu thật từ gan-nhan-chuyen-the.csv =====
   34 bộ là series, 0 bộ là phim điện ảnh, 28 bộ chưa chuyển thể.
   Vì 3 nhóm lệch nhau quá (0 / 34 / 28) nên KHÔNG xếp 2 hộp song song nữa
   — gộp về 1 hộp có tab, tab rỗng vẫn giữ để bạn thấy rõ là chưa có dữ liệu. */
const byTitle=t=>LIB.find(x=>x.title===t);
const ADAPT={phim:LIB.filter(n=>n.adapt==='phim'),
             series:LIB.filter(n=>n.adapt==='series'),
             none:LIB.filter(n=>!n.adapt)};
const LTABS=[
  {k:'series',l:'Series',c:ADAPT.series.length,ic:'tv',
   d:'Truyện đã dựng thành series truyền hình — nhóm theo tên phim, franchise nhiều phần xếp trước.'},
  {k:'phim',l:'Movie',c:ADAPT.phim.length,ic:'film',
   d:'Truyện đã dựng thành phim điện ảnh.'},
  {k:'none',l:'Chưa chuyển thể',c:ADAPT.none.length,ic:'book',
   d:'Truyện chưa được gắn nhãn chuyển thể trong file CSV.'}];
let ltab=(LTABS.find(t=>t.c>0)||LTABS[0]).k, lAll=false;
const LSHOW=12;
function srow(parts,name){
  const covers=parts.map(t=>{const n=byTitle(t);return n&&n.thumb?`<img src="${n.thumb}" alt="" loading="lazy">`:''}).join('');
  const yrs=uniq(parts.map(t=>{const n=byTitle(t);return n&&n.year}).filter(Boolean)).sort();
  const f=byTitle(parts[0]);
  return `<button class="srow" type="button" data-t="${esc(parts[0])}" title="Mở trang truyện: ${esc(name)}">
    <span class="sc">${covers}</span>
    <span class="st"><b>${esc(name)}</b><em>${parts.length>1?parts.length+' phần · ':''}${esc(yrs.join(', '))}${f&&f.countLabel?' · '+esc(f.countLabel):''}</em></span>
    ${parts.length>1?`<span class="mul">×${parts.length}</span>`:''}</button>`;
}
/* Dải tab chỉ vẽ MỘT lần rồi cập nhật class .on — nếu vẽ lại mỗi lần bấm thì
   nút vừa bấm bị thay bằng nút mới và MẤT FOCUS (người dùng bàn phím/tab
   screen reader đang ở đâu sẽ bị văng ra ngoài). */
function buildLtabs(){
  $('#ltabs').innerHTML=LTABS.map(t=>`<button class="ltab" data-k="${t.k}" type="button" role="tab" aria-selected="false">${ic(t.ic)}${esc(t.l)}<span class="ct">${t.c}</span></button>`).join('');
}
function syncLtabs(){
  $$('#ltabs .ltab').forEach(b=>{const on=b.dataset.k===ltab;
    b.classList.toggle('on',on);b.setAttribute('aria-selected',on?'true':'false');});
}
function renderLadder(){
  syncLtabs();
  $('#ldesc').textContent=LTABS.find(t=>t.k===ltab).d;
  $('#adSub').textContent=`${ADAPT.phim.length} phim điện ảnh · ${ADAPT.series.length} series · ${ADAPT.none.length} chưa chuyển thể / ${LIB.length} bộ`;
  const box=$('#lcontent'), ex=$('#adExpand');
  if(ltab==='phim'){
    box.innerHTML = ADAPT.phim.length
      ? `<div class="sgrid">${ADAPT.phim.map(n=>srow([n.title],n.adaptName||n.title)).join('')}</div>`
      : `<div class="lempty"><b>0/${LIB.length} bộ</b> được gắn nhãn <b>phim điện ảnh</b> trong file <code>gan-nhan-chuyen-the.csv</code> bạn gửi —
         toàn bộ ${ADAPT.series.length} bộ đã chuyển thể đều là <b>series truyền hình</b>, nên dữ liệu thật nằm ở tab <b>Series</b>.
         Sau này có bộ nào dựng thành phim điện ảnh thì chỉ cần đổi nhãn trong CSV thành <code>phim</code> rồi chạy lại
         <code>python3 labels.py</code> — khối này tự có dữ liệu, không phải sửa giao diện.</div>`;
    ex.style.display='none';
  } else {
    const items = ltab==='series' ? SERIES.map(g=>({name:g.name,parts:g.parts}))
                                  : ADAPT.none.map(n=>({name:n.title,parts:[n.title]}));
    const shown = lAll ? items : items.slice(0,LSHOW);
    box.innerHTML=`<div class="sgrid">${shown.map(g=>srow(g.parts,g.name)).join('')}</div>`;
    if(items.length>LSHOW){
      ex.style.display='';
      ex.innerHTML=(lAll?'Thu gọn':`Xem tất cả ${items.length} mục`)+ic(lAll?'up':'down');
    } else ex.style.display='none';
  }
}
buildLtabs();
renderLadder();
$('#ltabs').setAttribute('role','tablist');
$('#ltabs').addEventListener('click',e=>{const b=e.target.closest('.ltab');if(!b)return;ltab=b.dataset.k;lAll=false;renderLadder();});
$('#adExpand').addEventListener('click',()=>{lAll=!lAll;renderLadder();});
$('#adExpand').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();lAll=!lAll;renderLadder();}});

/* ===== lọc + phân trang ===== */
const years=uniq(LIB.map(n=>n.year)).sort((a,b)=>b-a);
const authors=uniq(LIB.map(n=>n.author)).sort((a,b)=>a.localeCompare(b,'vi'));
const couples=uniq(LIB.map(n=>n.couple)).sort((a,b)=>a.localeCompare(b,'vi'));
const state={status:'all',year:null,author:null,couple:null,q:'',sort:'new',page:1,per:12};
const TABS=[{k:'all',l:'Tất cả',c:LIB.length},
 {k:'Hoàn thành',l:'Hoàn thành',c:LIB.filter(n=>n.status==='Hoàn thành').length},
 {k:'Đang cập nhật',l:'Đang cập nhật',c:LIB.filter(n=>n.status==='Đang cập nhật').length},
 {k:'Sắp ra mắt',l:'Sắp ra mắt',c:LIB.filter(n=>n.status==='Sắp ra mắt').length},
 {k:'18+',l:'18+',c:LIB.filter(n=>n.is18).length},
 {k:'movie',l:'Movie',c:LIB.filter(n=>n.adapt==='phim').length},
 {k:'series',l:'Series',c:LIB.filter(n=>n.adapt==='series').length},
 {k:'no',l:'Chưa chuyển thể',c:LIB.filter(n=>!n.adapt).length}];
$('#tabs').innerHTML=TABS.map((t,i)=>`<button class="tab ${i===0?'on':''}" data-k="${esc(t.k)}">${esc(t.l)}<span class="ct">${t.c}</span></button>`).join('');
$('#fbar').innerHTML=['year','author','couple'].map(k=>{
  const label={year:'Năm',author:'Tác giả',couple:'Couple diễn viên'}[k];
  const vals={year:years.map(y=>[y,LIB.filter(n=>n.year===y).length]),
              author:authors.map(a=>[a,LIB.filter(n=>n.author===a).length]),
              couple:couples.map(c=>[c,LIB.filter(n=>n.couple===c).length])}[k];
  return `<div class="fdrop" data-drop="${k}"><button class="fbtn" type="button">${ic('down')}<span class="lbl">${label}</span></button>
    <div class="fpanel"><input class="fsearch" placeholder="Tìm trong ${label.toLowerCase()}…" data-for="${k}">
    <div class="flist"><button class="fopt on" data-k="${k}" data-v="" type="button">Tất cả<span class="n">${LIB.length}</span></button>
    ${vals.map(([v,c])=>`<button class="fopt" data-k="${k}" data-v="${esc(v)}" type="button">${esc(v)}<span class="n">${c}</span></button>`).join('')}</div>
    </div></div>`;}).join('')
+`<select class="sortsel" id="sortsel">
  <option value="new">Sắp xếp: Mới cập nhật</option><option value="year-desc">Năm mới nhất</option>
  <option value="year-asc">Năm cũ nhất</option><option value="chap-desc">Nhiều chương nhất</option>
  <option value="az">Tên A–Z</option></select>`;
function filtered(){
  let l=LIB.slice();const s=state.status;
  if(s==='18+') l=l.filter(n=>n.is18);
  else if(s==='movie') l=l.filter(n=>n.adapt==='phim');
  else if(s==='series') l=l.filter(n=>n.adapt==='series');
  else if(s==='no') l=l.filter(n=>!n.adapt);
  else if(s!=='all') l=l.filter(n=>n.status===s);
  if(state.year) l=l.filter(n=>n.year===state.year);
  if(state.author) l=l.filter(n=>n.author===state.author);
  if(state.couple) l=l.filter(n=>n.couple===state.couple);
  if(state.q){const q=state.q.toLowerCase();
    l=l.filter(n=>n.title.toLowerCase().includes(q)||n.author.toLowerCase().includes(q)||(n.couple||'').toLowerCase().includes(q));}
  const so=state.sort;
  l.sort((a,b)=> so==='az'? a.title.localeCompare(b.title,'vi')
    : so==='year-asc'? (+a.year-+b.year)||a.title.localeCompare(b.title,'vi')
    : so==='chap-desc'? (b.chapters-a.chapters)||a.title.localeCompare(b.title,'vi')
    : so==='year-desc'? (+b.year-+a.year)||a.title.localeCompare(b.title,'vi')
    : (String(b.updated||'')>String(a.updated||'')?1:String(b.updated||'')<String(a.updated||'')?-1:0)||a.title.localeCompare(b.title,'vi'));
  return l;
}
function pageList(total,cur){
  const out=[];
  if(total<=7){for(let i=1;i<=total;i++)out.push(i);return out;}
  out.push(1); if(cur>3) out.push('...');
  for(let i=Math.max(2,cur-1);i<=Math.min(total-1,cur+1);i++) out.push(i);
  if(cur<total-2) out.push('...');
  out.push(total); return out;
}
function renderPager(total,el,onGo,acc){
  if(total<=1){el.innerHTML='';return;}
  acc=acc||{get:()=>state.page,set:v=>{state.page=v;}};
  const cur=acc.get();
  el.innerHTML=`<div class="pgbtns">
    <button class="pg ${cur===1?'off':''}" data-go="${cur-1}">${ic('left')} Trước</button>
    ${pageList(total,cur).map(p=> p==='...'?'<span class="pg dots">…</span>'
      :`<button class="pg ${p===cur?'on':''}" data-go="${p}">${p}</button>`).join('')}
    <button class="pg ${cur===total?'off':''}" data-go="${cur+1}">Sau ${ic('right')}</button>
  </div><div class="pginfo">Trang ${cur}/${total}</div>`;
  $$('.pg[data-go]',el).forEach(b=>b.addEventListener('click',()=>{
    const p=+b.dataset.go; if(p<1||p>total||p===cur) return; acc.set(p); onGo();}));
}
function render(){
  const l=filtered();
  const total=Math.max(1,Math.ceil(l.length/state.per));
  if(state.page>total) state.page=1;
  const slice=l.slice((state.page-1)*state.per,state.page*state.per);
  $('#grid').innerHTML = slice.length? slice.map(card).join('')
    :`<div class="empty" style="grid-column:1/-1"><div class="big">Không có truyện nào khớp</div>Thử bỏ một vài tiêu chí lọc.
      <div style="margin-top:11px"><button class="btn ghost" id="emptyClr">Xoá tất cả lọc</button></div></div>`;
  renderPager(total,$('#pager'),()=>{render();document.querySelector('#grid').scrollIntoView({behavior:reduce?'auto':'smooth',block:'start'});});
  const picked=[];
  if(state.status!=='all'){const t=TABS.find(t=>t.k===state.status);picked.push([t?t.l:state.status,()=>{state.status='all';}]);}
  ['year','author','couple'].forEach(k=>{if(state[k]) picked.push([state[k],()=>{state[k]=null;}]);});
  $('#fpick').innerHTML = picked.length
    ? picked.map(([t],i)=>`<span class="fchip">${esc(t)} <span data-rm="${i}">${ic('x')}</span></span>`).join('')
      +'<button class="fclear" type="button" id="clr">Xoá tất cả lọc</button>' : '';
  $('#fcount').innerHTML=`${l.length} truyện`+(picked.length?' · đang lọc '+picked.length+' tiêu chí':'')+(total>1?' · trang '+state.page+'/'+total:'');
  $$('#fpick [data-rm]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();picked[+b.dataset.rm][1]();state.page=1;sync();render();}));
  const c=$('#clr'); if(c) c.addEventListener('click',()=>{state.status='all';state.year=state.author=state.couple=null;state.q='';$('#q1').value='';state.page=1;sync();render();});
  const ec=$('#emptyClr'); if(ec) ec.addEventListener('click',()=>{state.status='all';state.year=state.author=state.couple=null;state.q='';$('#q1').value='';state.page=1;sync();render();});
  animateCards($('#grid')); syncTabs();
}
function syncTabs(){$$('#tabs .tab').forEach(t=>t.classList.toggle('on',t.dataset.k===state.status));}
function sync(){
  syncTabs();
  $$('.fdrop').forEach(d=>{
    const k=d.dataset.drop,btn=d.querySelector('.fbtn');
    btn.classList.toggle('act',!!state[k]);
    d.querySelector('.lbl').textContent=state[k]||{year:'Năm',author:'Tác giả',couple:'Couple diễn viên'}[k];
    $$('.fopt',d).forEach(o=>o.classList.toggle('on',(o.dataset.v||'')===(state[k]||'')));
  });
}
$('#tabs').addEventListener('click',e=>{const b=e.target.closest('.tab');if(!b)return;
  state.status=b.dataset.k;state.page=1;sync();render();});
$('#fbar').addEventListener('click',e=>{
  const btn=e.target.closest('.fbtn');
  if(btn){const p=btn.parentElement.querySelector('.fpanel');
    const open=p.classList.contains('open');$$('.fpanel').forEach(x=>x.classList.remove('open'));
    p.classList.toggle('open',!open); if(!open) setTimeout(()=>p.querySelector('.fsearch').focus(),30); return;}
  const opt=e.target.closest('.fopt');
  if(opt){state[opt.dataset.k]=opt.dataset.v||null;state.page=1;$$('.fpanel').forEach(x=>x.classList.remove('open'));sync();render();}
});
$('#fbar').addEventListener('input',e=>{
  const s=e.target.closest('.fsearch'); if(!s)return;
  const q=s.value.trim().toLowerCase();
  $$('.fopt',s.closest('.fpanel')).forEach(o=>{o.style.display=(!o.dataset.v||o.dataset.v.toLowerCase().includes(q))?'':'none';});
});
document.addEventListener('click',e=>{if(!e.target.closest('.fdrop'))$$('.fpanel').forEach(x=>x.classList.remove('open'));});
$('#sortsel').addEventListener('change',e=>{state.sort=e.target.value;state.page=1;render();});
$('#q1').addEventListener('input',e=>{state.q=e.target.value.trim();state.page=1;render();});
sync();render();

/* ===== trang truyện — RENDER ĐỘNG =====
   Bản trước trang chi tiết bị "đóng cứng" vào 1 bộ, nên bấm thẻ truyện hay
   bấm một mục ở khối chuyển thể đều không có gì xảy ra. Giờ bấm vào đâu thì
   trang truyện đổi sang đúng bộ đó: bìa, mô tả, thông tin, số chương, nhãn
   chuyển thể, danh sách chương và 3 khối truyện liên quan. */
const CH_DEMO=null;
let dCur=null,chPage=1,chSort='new',chQ='',chList=[];
const CH_PER=12;
const stPill=x=>`<span class="stpill ${stCls(x)}"><span class="d"></span>${esc(x)}</span>`;
const nowChapter=n=>{try{const v=parseInt(localStorage.getItem('chuseoz-prog-'+(n.postId||n.slug))||'0',10);if(v)return v;}catch(e){}return parseInt(String((n&&n.countLabel)||'').split('/')[0],10)||1;};
function adaptText(n){
  const extra=(n.adaptName&&n.adaptName!==n.title)?' · '+n.adaptName:'';
  return n.adapt==='phim' ? 'Phim điện ảnh'+extra
       : n.adapt==='series' ? 'Series'+extra
       : 'Chưa chuyển thể';
}
function renderDetail(n){
  if(!document.getElementById('dwrap'))return;
  dCur=n;
  window.CZCUR=n;
  $('#dTitle').textContent=n.title;$('#dName').textContent=n.title;
  $('#dCover').src=n.slide||n.thumb||'';
  $('#d18').style.display=n.is18?'':'none';
  const first=String(n.countLabel||'').split('/')[0];
  $('#dReadFrom').textContent=(first&&first!=='0')?first:'1';
  $('#dSyn').textContent=n.synFull||n.syn||'';
  $('#dMeta2').innerHTML=[`<span>${esc(n.year)}</span>`,`<span>cập nhật ${esc(n.updated||'—')}</span>`,
    `<span>${esc(n.author)}</span>`,n.couple?`<span>${esc(n.couple)}</span>`:'',stPill(n.status)].join('');
  $('#dTable').innerHTML=[['Tình trạng',n.status],['Tác giả',n.author],['Couple',n.couple||'Chưa cập nhật'],
    ['Số chương',n.countLabel],['Chuyển thể',adaptText(n)]]
    .map(([k,v])=>`<div class="r"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('');
  const tot=parseInt(String(n.countLabel||'').split('/')[1],10)||0;
  chList=Array.from({length:Math.max(1,tot||0)},(_,i)=>'Chương '+(i+1));
  $('#dChcount').textContent=n.countLabel+' · '+chList.length+' chương';
  chPage=1;chQ='';$('#chapq').value='';
  renderChaps();
  const sameCouple=n.couple?LIB.filter(x=>x.couple===n.couple&&x.slug!==n.slug).slice(0,4):[];
  const sameAuthor=LIB.filter(x=>x.author===n.author&&x.slug!==n.slug).slice(0,4);
  const grp=SERIES.find(g=>g.parts.length>1&&g.parts.indexOf(n.title)>=0);
  const sameSeries=grp?grp.parts.filter(p=>p!==n.title).map(byTitle).filter(Boolean):[];
  relBox(sameSeries,$('#relSeries'));
  relBox(sameCouple,$('#relCouple'));
  relBox(sameAuthor,$('#relAuthor'));
}
function renderChaps(){
  const now=nowChapter(dCur);
  let list=chList.map((t,i)=>({t,i:i+1})).filter(c=>!chQ||c.t.toLowerCase().includes(chQ)||String(c.i)===chQ);
  if(chSort==='new') list=list.slice().reverse();
  const total=Math.max(1,Math.ceil(list.length/CH_PER));
  if(chPage>total) chPage=1;
  const slice=list.slice((chPage-1)*CH_PER,chPage*CH_PER);
  $('#chapgrid').innerHTML=slice.length?slice.map(c=>`<div class="cha ${c.i===now?'now':''}" title="${c.i===now?'Bạn đang đọc tới đây':'Đọc chương '+c.i}">
    <span class="no">${c.i}</span><span class="nm">${esc(c.t)}</span>${c.i<now?`<span class="done">${ic('check')}</span>`:''}</div>`).join('')
    :'<div class="empty" style="grid-column:1/-1">Không tìm thấy chương nào.</div>';
  renderPager(total,$('#chapPager'),()=>renderChaps(),{get:()=>chPage,set:v=>{chPage=v;}});
}
function relBox(list,el){
  const box=el.parentElement;
  if(!list||!list.length){box.style.display='none';return;}
  box.style.display='';
  el.innerHTML=list.map(card).join('');animateCards(el);
}
function openDetail(title){
  const n=LIB.find(x=>x.title===title);if(!n)return;
  renderDetail(n);
  const dt=$('#dTitle'); const br=dt?dt.closest('.browser'):null;
  if(br) br.scrollIntoView({behavior:reduce?'auto':'smooth',block:'start'});
}
/* bộ mở sẵn khi vào bản xem trước: bộ có nhiều liên hệ nhất */
const cntf=(f,v)=>LIB.filter(n=>f(n)===v).length;
renderDetail(LIB.slice().sort((a,b)=>((b.couple?cntf(x=>x.couple,b.couple):0)*3+cntf(x=>x.author,b.author))
  -((a.couple?cntf(x=>x.couple,a.couple):0)*3+cntf(x=>x.author,a.author)))[0]);
var _cq=$('#chapq'); if(_cq)_cq.addEventListener('input',e=>{chQ=e.target.value.trim().toLowerCase();chPage=1;renderChaps();});
var _csn=$('#chapSortNew'),_cso=$('#chapSortOld');
if(_csn)_csn.addEventListener('click',function(){chSort='new';this.classList.add('on');if(_cso)_cso.classList.remove('on');chPage=1;renderChaps();});
if(_cso)_cso.addEventListener('click',function(){chSort='old';this.classList.add('on');if(_csn)_csn.classList.remove('on');chPage=1;renderChaps();});
/* bấm thẻ truyện (thư viện / truyện liên quan) hoặc 1 mục ở khối chuyển thể */
document.addEventListener('click',e=>{
  const t=e.target.closest('.card[data-t],.srow[data-t]');
  if(t) openDetail(t.dataset.t);
});
/* menu Movie / Series trên header → tới khối chuyển thể và chọn đúng tab */
$$('.nav a').forEach(a=>a.addEventListener('click',()=>{
  const l=a.textContent.trim();
  const k=l==='Movie'?'phim':l==='Series'?'series':null;
  if(!k)return;
  ltab=k;lAll=false;renderLadder();
  const sec=$('#secAdapt'); if(sec) sec.scrollIntoView({behavior:reduce?'auto':'smooth',block:'start'});
}));

/* route: #truyen-<slug> = mở TRANG TRUYỆN toàn màn hình trên home */
function routeBook(){
  var m=location.hash.match(/^#truyen-(.+)$/),n=null;
  if(m){var sl=decodeURIComponent(m[1]);
    for(var i=0;i<LIB.length;i++){if((LIB[i].slug||'')===sl||(LIB[i].title||'')===sl){n=LIB[i];break;}}}
  var app=document.getElementById('app');
  if(n){app.dataset.view='book';renderDetail(n);window.scrollTo(0,0);}
  else if(app.dataset.view){delete app.dataset.view;window.scrollTo(0,0);}
}
window.addEventListener('hashchange',routeBook);
routeBook();
var _db=$('#dBack'); if(_db)_db.addEventListener('click',function(){location.hash='';});
})();

