/* ---------- phần theme thêm: điều hướng thật + nhớ sáng/tối + registry mới ---------- */
(function(){
  var app=document.getElementById('app');
  try{var d=localStorage.getItem('chuseoz-dir');if(d&&app)app.dataset.dir=d;}catch(e){}
  if(app&&document.body)document.body.setAttribute('data-dir',app.dataset.dir||'c');
  document.addEventListener('click',function(e){
    var el=e.target;
    if(!el||!el.closest)return;
    if(el.closest('#themeBtn')){setTimeout(function(){try{localStorage.setItem('chuseoz-dir',app.dataset.dir);}catch(e){}document.body.setAttribute('data-dir',app.dataset.dir||'c');},0);return;}
    var b=el.closest('#dwrap .btn.primary');
    if(b&&window.CZCUR&&CZCUR.url){
      var k=parseInt((document.getElementById('dReadFrom')||{}).textContent||'1',10)||1;
      location.href=CZCUR.url+'#page-'+k;return;}
    var cd=el.closest('.card[data-t],.srow[data-t]');
    if(cd){
      var reg=(window.CZREG&&CZREG.lib)||[],nn=null,tt=cd.getAttribute('data-t');
      for(var i2=0;i2<reg.length;i2++){if(reg[i2].title===tt){nn=reg[i2];break;}}
      if(nn){location.hash='truyen-'+encodeURIComponent(nn.slug||nn.title);}
      return;}
    var c=el.closest('#chapgrid .cha');
    if(c&&window.CZCUR&&CZCUR.url){
      var no=c.querySelector('.no');location.href=CZCUR.url+'#page-'+(no?no.textContent.trim():1);return;}
  });
  /* trang /p/data.html chứa <div id="czdata">{json}</div> — bản dữ liệu mới hơn */
  try{
    fetch('/p/data.html',{cache:'no-store'}).then(function(r){return r.ok?r.text():'';}).then(function(html){
      if(!html)return;
      var m=html.match(/<div id=["']?czdata["']?>([\s\S]*?)<\/div>/);
      if(!m)return;
      var j=JSON.parse(m[1].replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&amp;/g,'&'));
      var cur=window.CZREG||{};
      if(j&&j.rev&&j.rev>(cur.rev||'')){localStorage.setItem('chuseoz-reg',JSON.stringify(j));location.reload();}
    }).catch(function(){});
  }catch(e){}
})();

